selector_to_html = {"a[href=\"#bashbrew-build\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">bashbrew-build<a class=\"headerlink\" href=\"#bashbrew-build\" title=\"Link to this heading\">#</a></h1><p>Execute the strategy generated by <a class=\"reference internal\" href=\"bashbrew-jobs.html\"><span class=\"doc std std-doc\">bashbrew-jobs</span></a>.  This action\nskips unspecified steps without raising an error.</p><p>Uploading the built image to a container registry is the\nresponsibility of the caller.</p>", "a[href=\"#inputs\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Inputs<a class=\"headerlink\" href=\"#inputs\" title=\"Link to this heading\">#</a></h2>", "a[href=\"bashbrew-jobs.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">bashbrew-jobs<a class=\"headerlink\" href=\"#bashbrew-jobs\" title=\"Link to this heading\">#</a></h1><p>Output a GitHub Actions\n<a class=\"reference external\" href=\"https://docs.github.com/actions/how-tos/write-workflows/choose-what-workflows-do/run-job-variations\">matrix strategy</a>\nthat builds and tests Docker Official Images Library-style container\nbimages.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
